from pathlib import Path
p=Path('outputs/handcricket.html');s=p.read_text(encoding='utf-8-sig')
s=s.replace("musicTimer:null};", "musicTimer:null,musicNodes:[],musicGain:null};",1)
a=s.index('function musicStart()');b=s.index('function musicStop()',a)
new="""function musicStart(){if(!S.musicOn||S.musicVolume<=0||!audio)return;try{ac??=new audio();if(ac.state!=='running'){ac.resume().catch(()=>{});return}}catch(e){return}if(S.musicNodes.length)return;try{const bus=ac.createGain(),filter=ac.createBiquadFilter();bus.gain.setValueAtTime(S.musicVolume*.62,ac.currentTime);filter.type='lowpass';filter.frequency.value=1800;filter.Q.value=.45;bus.connect(filter);filter.connect(ac.destination);S.musicGain=bus;const addTone=(freq,type,level,detune=0)=>{const osc=ac.createOscillator(),gain=ac.createGain();osc.type=type;osc.frequency.value=freq;osc.detune.value=detune;gain.gain.value=level;osc.connect(gain);gain.connect(bus);osc.start();S.musicNodes.push(osc,gain)};[[130.81,'triangle',.045,-3],[164.81,'sine',.035,2],[196,'triangle',.028,-2],[261.63,'sine',.018,3],[55,'sine',.14,0],[82.41,'sine',.035,0],[392,'sine',.009,0]].forEach(x=>addTone(...x));const lfo=ac.createOscillator(),depth=ac.createGain();lfo.type='sine';lfo.frequency.value=.22;depth.gain.value=.014;lfo.connect(depth);depth.connect(bus.gain);lfo.start();S.musicNodes.push(lfo,depth)}catch(e){console.warn('Background music could not start',e)}}"""
s=s[:a]+new+s[b:]
s=s.replace("function musicStop(){clearInterval(S.musicTimer);S.musicTimer=null}","function musicStop(){clearInterval(S.musicTimer);S.musicTimer=null;S.musicNodes.forEach(n=>{try{n.stop?.();n.disconnect()}catch(e){}});S.musicNodes=[];if(S.musicGain){try{S.musicGain.disconnect()}catch(e){}S.musicGain=null}}")
s=s.replace("$('#setMusicVol').oninput=e=>{S.musicVolume=+e.target.value;S.musicVolume?musicStart():musicStop();saveSettings()};", "$('#setMusicVol').oninput=e=>{S.musicVolume=+e.target.value;if(S.musicGain)S.musicGain.gain.setTargetAtTime(S.musicVolume*.62,ac.currentTime,.08);S.musicVolume?musicStart():musicStop();saveSettings()};")
p.write_text(s,encoding='utf-8')
